BEGIN;

INSERT INTO public.subjects (slug, name, description, color, sort_order, is_active)
VALUES ('stats-basics', '統計学の基礎（図解ドリル） Set 1 記述統計',
        '統計の用語を、前提知識ゼロでも分かる解説と1枚の図で腹落ちさせる図解ドリル。問題は入口、主役は解説。Set 1はデータのようす（記述統計）。',
        '#6ab08d', 140, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
JOIN (VALUES
  ('データのようす（記述統計）', '#58a6ff', 0),
  ('確率と分布', '#3fb950', 1),
  ('推測統計', '#d2a8ff', 2),
  ('仮説検定', '#e3a008', 3),
  ('相関と回帰', '#f778ba', 4),
  ('因果推論', '#ffa657', 5),
  ('ベイズ統計', '#a5d6ff', 6),
  ('機械学習との接点', '#7ee787', 7)
) AS v(name, color, sort_order) ON true
WHERE s.slug = 'stats-basics'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats1-q01', 'データのようす（記述統計）',
   'クラスの記録係が4種類のデータを集めた。このうち「平均を計算して意味がある」のはどれ？',
   NULL::text,
   '["全員の身長（cm）", "好きな給食の人気メニュー", "全員の出席番号", "全員の血液型"]',
   0, '[0]', 'single',
   '{"asked": "数字の顔をしたデータと、本当に計算してよいデータの見分け方。", "point": "たし算や平均に意味があるなら量的変数、種類の名前なら質的変数。出席番号は数字でも「名札」。", "kid": "データには2種類ある。身長や点数のように「量をはかった数字」（量的変数）と、血液型やメニューのように「種類の名前」（質的変数）。平均が使えるのは量的変数だけ。", "eg": "背番号10番の選手と20番の選手を足しても「30番の選手」にはならない。背番号は選手を区別する名札であって、量ではないから。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"170\" y1=\"14\" x2=\"170\" y2=\"136\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"88\" y=\"28\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">量的変数</text><text x=\"88\" y=\"44\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">量をはかった数字</text><text x=\"88\" y=\"74\" fill=\"#60a5fa\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"600\">158  165  172  180</text><text x=\"88\" y=\"100\" fill=\"#6ab08d\" font-size=\"10\" text-anchor=\"middle\">たし算・平均ができる</text><text x=\"88\" y=\"118\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">平均 168.8cm</text><text x=\"254\" y=\"28\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">質的変数</text><text x=\"254\" y=\"44\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">種類の名前（ラベル）</text><text x=\"254\" y=\"74\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">A型  B型  O型  AB型</text><text x=\"254\" y=\"100\" fill=\"#c47070\" font-size=\"10\" text-anchor=\"middle\">数えることしかできない</text><text x=\"254\" y=\"118\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">「平均の血液型」は無い</text></svg>", "terms": [["量的変数", "身長・点数・気温のように、量として測った数字。たし算や平均ができる"], ["質的変数", "血液型・メニュー名のように、種類を表すラベル。数えることしかできない"], ["代表値", "たくさんのデータを1つの数字で代表させたもの。平均値・中央値など"]], "think": "見分けるコツは「その数字を足したり平均したりして意味があるか」を想像すること。身長165cmと175cmの平均170cmには意味がある。でも出席番号3番と5番を足して「平均4番」と言っても何も分からない。数字の形をしていても、順番や区別のためのラベルなら質的変数の仲間。", "vs": "「数字かどうか」で分けるのではなく「量をはかったものかどうか」で分ける。出席番号・電話番号・郵便番号はぜんぶ数字だが、量ではないので質的変数の扱い。", "why_asked": "統計の道具（平均・分散・相関など）には「量的変数用」「質的変数用」の区別がある。最初にデータの種類を見分けられないと、そのあとの道具選びを全部間違える。だからどの教科書もここから始まる。", "usecase": "アンケート集計で「満足度（5段階）の平均は3.8」は計算するが、「好きなブランドの平均」は計算できないので件数の割合で見る。Excelや分析ツールで最初に列の型を決める作業が、まさにこの見分け。", "opt": ["正解。身長は量をはかった数字（量的変数）なので、たし算も平均も意味がある。", "メニュー名は種類を表すラベル（質的変数）。「カレーとラーメンの平均」は計算できず、人気の数を数えることしかできない。", "出席番号は数字の形をしているが、人を区別するための名札。平均出席番号を出しても何も分からない。", "血液型は種類の名前（質的変数）。足して平均することはできず、各型の人数を数えるのが正しい扱い。"]}'),

  ('stats1-q02', 'データのようす（記述統計）',
   '5人のテストの点数は 40点、50点、60点、70点、90点だった。平均値は何点？',
   NULL::text,
   '["62点", "60点", "65点", "70点"]',
   0, '[0]', 'single',
   '{"asked": "平均値の計算のしかたと、その数字が表している意味。", "point": "平均値は「全部たして人数で割る」。40+50+60+70+90=310、310÷5=62点。", "kid": "平均値は「全員の点数をいったん全部集めて、全員に同じ数ずつ配り直したら1人ぶんはいくつになるか」という数。合計を人数で山分けした値。", "eg": "5人がお菓子を40個、50個、60個、70個、90個持っている。全部集めると310個。それを5人で同じ数ずつ分け直すと1人62個。この62が平均。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"20\" y1=\"78\" x2=\"320\" y2=\"78\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"78\" x2=\"20\" y2=\"84\" stroke=\"#2a2f3f\"/><text x=\"20\" y=\"98\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><line x1=\"170\" y1=\"78\" x2=\"170\" y2=\"84\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"98\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">50</text><line x1=\"320\" y1=\"78\" x2=\"320\" y2=\"84\" stroke=\"#2a2f3f\"/><text x=\"320\" y=\"98\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">100</text><circle cx=\"140\" cy=\"70\" r=\"5\" fill=\"#60a5fa\"/><text x=\"140\" y=\"56\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">40</text><circle cx=\"170\" cy=\"70\" r=\"5\" fill=\"#60a5fa\"/><text x=\"170\" y=\"56\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">50</text><circle cx=\"200\" cy=\"70\" r=\"5\" fill=\"#60a5fa\"/><text x=\"200\" y=\"56\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">60</text><circle cx=\"230\" cy=\"70\" r=\"5\" fill=\"#60a5fa\"/><text x=\"230\" y=\"56\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">70</text><circle cx=\"290\" cy=\"70\" r=\"5\" fill=\"#60a5fa\"/><text x=\"290\" y=\"56\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">90</text><polygon points=\"206,80 197,98 215,98\" fill=\"#3b82f6\"/><text x=\"206\" y=\"116\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">平均 62点</text><text x=\"206\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">全体がちょうどつり合う支点</text></svg>", "terms": [["平均値", "合計を個数で割った値。データ全体の重さの中心"], ["代表値", "データ全体を1つの数字で代表させる値。平均値はその代表選手"]], "think": "平均値の正体は「データ全体のつり合いの位置」。数直線の上に点数の場所ごとにビー玉を置いたと想像すると、板がちょうどつり合う支点の位置が平均値になる。だから大きい値にも小さい値にも引っ張られながら、全体の重心に落ち着く。", "vs": "中央値（このデータでは60点）は「順に並べた真ん中の人」の値で、平均値（62点）とは別物。90点という大きめの値があるぶん、平均は中央値より少し高い方に引っ張られている。", "why_asked": "何十人・何万人のデータを1つずつ眺めても頭に入らない。「1つの数字に要約して比べられるようにする」のが代表値の役目で、平均値はその中でいちばんよく使われる基本の道具。", "usecase": "平均気温、平均点、平均年収、Webサイトの平均滞在時間。何かを「ざっくり1つの数字」で報告するとき、ほぼ必ず最初に出てくる。", "opt": ["正解。合計310点を5人で割って62点。", "60点は順に並べた真ん中の人の点数（中央値）。平均値は90点に少し引っ張られて、それより高くなる。", "65点は最大と最小だけを見て（40+90）÷2とした値。あいだの3人の点数が無視されている。", "70点は上から2番目の人の点数で、全体を代表する計算にはなっていない。"]}'),

  ('stats1-q03', 'データのようす（記述統計）',
   '5人の1か月のお小遣いは 500円、500円、600円、700円、5000円。中央値はいくら？',
   NULL::text,
   '["600円", "1460円", "500円", "700円"]',
   0, '[0]', 'single',
   '{"asked": "中央値の求め方と、極端な値に強い理由。", "point": "小さい順に並べて、ちょうど真ん中の人の値が中央値。5人なら3番目の600円。", "kid": "中央値は、全員を金額順に一列に並ばせたときの「真ん中の人」の値。1人だけ桁違いの5000円がいても、並び順の真ん中は動かない。", "eg": "身長順に並んだ5人の記念写真で、真ん中に立つ人が中央値。端の1人がどれだけ背が高くても、真ん中に立つ人は変わらない。", "viz": "<svg viewBox=\"0 0 340 124\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"30\" y1=\"72\" x2=\"245\" y2=\"72\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"262\" y1=\"72\" x2=\"315\" y2=\"72\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M249 64 l5 16 M254 64 l5 16\" stroke=\"#2a2f3f\" fill=\"none\"/><circle cx=\"52\" cy=\"64\" r=\"5\" fill=\"#60a5fa\"/><text x=\"52\" y=\"90\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">500円</text><circle cx=\"92\" cy=\"64\" r=\"5\" fill=\"#60a5fa\"/><text x=\"92\" y=\"90\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">500円</text><circle cx=\"132\" cy=\"64\" r=\"5\" fill=\"#3b82f6\"/><text x=\"132\" y=\"90\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">600円</text><circle cx=\"176\" cy=\"64\" r=\"5\" fill=\"#60a5fa\"/><text x=\"176\" y=\"90\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">700円</text><circle cx=\"296\" cy=\"64\" r=\"5\" fill=\"#c47070\"/><text x=\"296\" y=\"90\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">5000円</text><circle cx=\"132\" cy=\"64\" r=\"9\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"132\" y=\"36\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">中央値 600円（真ん中の人）</text><line x1=\"228\" y1=\"52\" x2=\"228\" y2=\"76\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/><text x=\"228\" y=\"44\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\">平均 1460円</text><text x=\"140\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">平均は1人の5000円に引っ張られる</text><text x=\"296\" y=\"44\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">外れ値</text></svg>", "terms": [["中央値", "小さい順に並べたときの真ん中の値。人数が偶数なら真ん中2人の平均"], ["外れ値", "仲間から大きく離れた値。ここでは5000円"], ["頑健（ロバスト）", "外れ値に影響されにくい性質のこと"]], "think": "平均値を計算すると（500+500+600+700+5000）÷5=1460円。でも5人のうち4人は700円以下なので、「代表は1460円」は誰の実感にも合わない。1人の5000円が平均を引っ張り上げたから。中央値は「並び順の真ん中」しか見ないので、端の値がどれだけ極端でも動かない。だから外れ値があるデータでは、中央値のほうが実態に近い代表になる。", "vs": "平均値は全員の金額を計算に使うので、外れ値に引っ張られる。中央値は真ん中の位置しか見ないので引っ張られない。「外れ値がありそうなら中央値」と覚える。", "why_asked": "年収や貯蓄額のように「一部の人だけ桁違いに大きい」データは世の中にとても多い。そこで平均を使うと実態とずれた数字になるので、中央値という道具が必要になった。", "usecase": "「世帯年収の中央値」「住宅価格の中央値」はニュースの定番。国の統計でも、貯蓄額のようにかたよった分布では平均と中央値の両方が発表される。", "opt": ["正解。小さい順に並べた3番目（真ん中の人）が600円。", "1460円は平均値。1人の5000円に引っ張られて、残り4人の実感よりずっと高い値になっている。", "500円は一番多く登場する値（最頻値）。真ん中の位置の値ではない。", "700円は真ん中より1つ上の人の値。5人の真ん中は3番目の人。"]}'),

  ('stats1-q04', 'データのようす（記述統計）',
   '靴屋の店長が「来月いちばん多く仕入れるべきサイズ」を知りたい。売れたサイズの記録から見るべき代表値はどれ？',
   NULL::text,
   '["最頻値", "平均値", "中央値", "最大値"]',
   0, '[0]', 'single',
   '{"asked": "「一番よく出る値」を知りたいときに使う代表値。", "point": "「実際に一番多く売れる、その値そのもの」を知りたいなら、登場回数が最多の値＝最頻値。", "kid": "最頻値は「データの中で一番たくさん現れた値」。多数決でいちばん票を集めた値のこと。", "eg": "クラスの誕生日会で買うケーキを決めるとき、「平均の味」は計算できないので、一番人気の味（多数決1位）を選ぶ。それが最頻値の考え方。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"46\" y=\"91\" width=\"34\" height=\"21\" rx=\"3\" fill=\"#2a2f3f\"/><text x=\"63\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">23cm</text><text x=\"63\" y=\"85\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">3足</text><rect x=\"100\" y=\"70\" width=\"34\" height=\"42\" rx=\"3\" fill=\"#2a2f3f\"/><text x=\"117\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">24cm</text><text x=\"117\" y=\"64\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">6足</text><rect x=\"154\" y=\"35\" width=\"34\" height=\"77\" rx=\"3\" fill=\"#3b82f6\"/><text x=\"171\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">25cm</text><text x=\"171\" y=\"29\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">11足</text><rect x=\"208\" y=\"63\" width=\"34\" height=\"49\" rx=\"3\" fill=\"#2a2f3f\"/><text x=\"225\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">26cm</text><text x=\"225\" y=\"57\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">7足</text><rect x=\"262\" y=\"98\" width=\"34\" height=\"14\" rx=\"3\" fill=\"#2a2f3f\"/><text x=\"279\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">27cm</text><text x=\"279\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2足</text><text x=\"171\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">最頻値＝一番多く売れた値</text><line x1=\"30\" y1=\"112\" x2=\"316\" y2=\"112\" stroke=\"#2a2f3f\"/></svg>", "terms": [["最頻値", "一番多く登場した値。英語でモード"], ["度数", "その値が登場した回数のこと"]], "think": "靴のサイズで平均を取ると「25.3cm」のような、実際には売っていない中途半端な値が出ることがある。店長が知りたいのは「現実に一番多く売れるサイズそのもの」なので、登場回数が最多の値を見るのが正しい。最頻値は、メニュー名のような質的変数にも使える唯一の代表値でもある。", "vs": "平均値・中央値は「分布の真ん中あたり」を教える値。最頻値は「一番人が集まっている場所」を教える値。山が2つある分布では、平均や中央値が「誰もいない谷間」を指すことがあり、違いがはっきり出る。", "why_asked": "「一番よくあるケースに備える」のは在庫・防災・シフト計画など、実務の基本の考え方。その1点をずばり教えてくれる代表値は最頻値だけ。", "usecase": "在庫の発注（一番売れるサイズや色）、コールセンターの「一番多い問い合わせ時間帯」、アンケートの「一番多かった回答」。", "opt": ["正解。一番多く登場した（一番売れた）サイズが最頻値。仕入れの主力はこれ。", "平均値は25.3cmのような実在しないサイズになりがちで、そのまま仕入れには使えない。", "中央値は並べて真ん中のサイズ。真ん中のサイズと一番売れるサイズは、一致するとは限らない。", "最大値は一番大きいサイズが分かるだけで、たくさん売れるかどうかとは関係がない。"]}'),

  ('stats1-q05', 'データのようす（記述統計）',
   'テストの点数が「どのあたりの点数に何人いるか」を山の形で見たい。使うグラフはどれ？',
   NULL::text,
   '["ヒストグラム", "円グラフ", "折れ線グラフ", "レーダーチャート"]',
   0, '[0]', 'single',
   '{"asked": "分布の形を見るための基本グラフの選び方。", "point": "「区間ごとの人数を柱の高さで見る」のがヒストグラム。分布の形を見たいときは、まずこれ。", "kid": "点数を「0〜10点、10〜20点…」のような区間（ビン）に区切り、それぞれの区間に入る人数を柱の高さで表したグラフ。柱が並ぶと、データがどこに集まっているかが山の形で一目で分かる。", "eg": "学年全員を、点数ごとの棟に分かれたマンションに住まわせるイメージ。「60点台の棟」に住人が多ければ、その棟だけ高くなる。マンション群を遠くから眺めた形が、分布の形。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"30\" y=\"109\" width=\"27\" height=\"7\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"58\" y=\"102\" width=\"27\" height=\"14\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"86\" y=\"88\" width=\"27\" height=\"28\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"114\" y=\"67\" width=\"27\" height=\"49\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"142\" y=\"46\" width=\"27\" height=\"70\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"170\" y=\"32\" width=\"27\" height=\"84\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"198\" y=\"53\" width=\"27\" height=\"63\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"226\" y=\"81\" width=\"27\" height=\"35\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"254\" y=\"95\" width=\"27\" height=\"21\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"282\" y=\"109\" width=\"27\" height=\"7\" fill=\"#3b82f6\" opacity=\"0.55\"/><line x1=\"30\" y1=\"116\" x2=\"310\" y2=\"116\" stroke=\"#2a2f3f\"/><text x=\"30\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0点</text><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">50点</text><text x=\"310\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">100点</text><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">区間ごとの人数を柱に → 山の形が見える</text></svg>", "terms": [["ヒストグラム", "数値を区間で区切り、区間ごとの個数を柱で表したグラフ"], ["ビン（階級）", "区切った1つ1つの区間のこと。「0〜10点」など"], ["分布", "データがどこにどれだけ散らばっているかの全体像"]], "think": "点数の表を眺めても「どこに人が多いか」は頭に入らない。区間ごとに人数を数えて柱の高さにすると、山が1つか2つか、左右どちらにすそが長いか、ポツンと離れた外れ値がいないか、が一目で分かる。データ分析で最初にヒストグラムを描くのはこのため。", "vs": "棒グラフは「カテゴリごとの量」を比べる道具で、棒のあいだにすき間がある。ヒストグラムは「連続した数値」を区間で区切る道具で、柱がくっついている。見た目は似ているが役目が違う。", "why_asked": "平均や分散は、分布を数字1つに圧縮した要約。要約する前に「そもそもどんな形か」を目で確かめないと、山が2つある分布の平均を信じるような失敗をする。", "usecase": "テストの得点分布、Webサービスの応答時間の分布、工場製品の寸法のばらつき確認。分析の実務では「まずヒストグラムを描け」が合言葉。", "opt": ["正解。区間ごとの人数を柱の高さで表し、分布の形（山のでき方）を見るグラフ。", "円グラフは全体に対する割合の内訳を見る道具。どの点数帯に何人いるかという形は分からない。", "折れ線グラフは時間による変化を追う道具。ある1回のテストの散らばり方を見るものではない。", "レーダーチャートは国語・数学…のような複数項目のバランスを見る道具で、1教科の分布は描けない。"]}'),

  ('stats1-q06', 'データのようす（記述統計）',
   'クラスの身長データの中に1件だけ「1650cm」という値が混ざっていた。このように仲間から極端に離れた値を何と呼ぶ？',
   NULL::text,
   '["外れ値", "偏差値", "最頻値", "代表値"]',
   0, '[0]', 'single',
   '{"asked": "仲間から極端に離れた値の名前と、正しい扱い方。", "point": "極端に離れた値は外れ値。消す前に、まず「入力ミスか、本物か」を調べる。", "kid": "外れ値は、他のデータからポツンと離れた値。原因は大きく2つで、「1650cm」のような入力ミス・測り間違いと、「本当にそういう特別な例だった」の2種類がある。", "eg": "徒競走の記録に1人だけ「3秒」がいたら、世界新記録ではなくストップウォッチの押し間違いをまず疑う。調べてそれでも本当に3秒なら、それは大発見。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"30\" y1=\"70\" x2=\"230\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"248\" y1=\"70\" x2=\"315\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M235 62 l5 16 M240 62 l5 16\" stroke=\"#2a2f3f\" fill=\"none\"/><circle cx=\"48\" cy=\"62\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"60\" cy=\"58\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"72\" cy=\"64\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"80\" cy=\"56\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"92\" cy=\"60\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"100\" cy=\"64\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"112\" cy=\"58\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"122\" cy=\"62\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"134\" cy=\"57\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"146\" cy=\"63\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"158\" cy=\"60\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"170\" cy=\"62\" r=\"4\" fill=\"#60a5fa\"/><text x=\"108\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">140〜190cm（ふつうの仲間）</text><circle cx=\"292\" cy=\"60\" r=\"5\" fill=\"#c47070\"/><text x=\"292\" y=\"42\" fill=\"#c47070\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">1650cm</text><text x=\"292\" y=\"92\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">外れ値</text><text x=\"170\" y=\"118\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">まず「入力ミス？ 本物？」を調べてから料理する</text></svg>", "terms": [["外れ値", "仲間から大きく離れた値。異常値と呼ぶこともある"], ["データクレンジング", "分析の前にミスや欠けを直してデータをきれいにする作業"]], "think": "外れ値がこわいのは、平均や分散のような「全員の値を使う計算」を、たった1件で大きく狂わせるから。1650cmが1件混ざるだけで、クラスの平均身長は何十cmも跳ね上がる。だから分析の前にヒストグラムや箱ひげ図で外れ値を探し、ミスなら直し、本物なら「入れた場合と外した場合」の両方を確かめるのが定石。", "vs": "外れ値は「離れた値そのもの」の名前。偏差値は「平均からの位置を50を基準に表したものさし」。言葉の雰囲気は似ているが、まったくの別物。", "why_asked": "実際のデータには入力ミス・単位の間違い・測定エラーが必ず混ざる。外れ値に気づかないまま平均を報告すると、結論ごと間違える。統計の失敗談の多くはここから生まれる。", "usecase": "分析前の前処理（データクレンジング）で最初にやる仕事。クレジットカードの不正利用検知は「ふだんと極端に違う使い方＝外れ値」を探す仕組みそのもの。", "opt": ["正解。仲間から極端に離れた値を外れ値と呼ぶ。まず入力ミスかどうかを調べる。", "偏差値は平均からの位置を50を基準に表した値で、離れた値そのものの名前ではない。", "最頻値は一番多く登場した値のこと。ポツンと離れた値とは、むしろ逆の存在。", "代表値は平均値や中央値のような「全体を代表する数字」の総称で、離れた1件を指す言葉ではない。"]}'),

  ('stats1-q07', 'データのようす（記述統計）',
   'A組もB組も平均は60点。でもA組は全員55〜65点に収まり、B組には20点や100点の人もいる。この「散らばり方の違い」を1つの数字で表すのはどれ？',
   NULL::text,
   '["分散", "平均値", "中央値", "合計点"]',
   0, '[0]', 'single',
   '{"asked": "平均だけでは見えない「ばらつき」を数字にする道具。", "point": "平均からの離れ具合（偏差）を2乗して平均したものが分散。大きいほど散らばっている。", "kid": "分散は「みんなが平均からどれくらい離れているか」の平均。全員が平均ぴったりなら0、点数がバラバラなほど大きくなる。", "eg": "同じ「平均気温15度」でも、1年中15度前後の街と、夏35度・冬マイナス5度の街では暮らしがまるで違う。この「平均が同じでも違う」を数字にしたのが分散。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"20\" y1=\"56\" x2=\"320\" y2=\"56\" stroke=\"#2a2f3f\"/><circle cx=\"176\" cy=\"48\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"185\" cy=\"48\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"194\" cy=\"48\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"200\" cy=\"48\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"206\" cy=\"48\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"215\" cy=\"48\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"224\" cy=\"48\" r=\"4.5\" fill=\"#60a5fa\"/><text x=\"24\" y=\"34\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">A組</text><text x=\"316\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">ばらつき小 → 分散 小</text><line x1=\"20\" y1=\"116\" x2=\"320\" y2=\"116\" stroke=\"#2a2f3f\"/><circle cx=\"80\" cy=\"108\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"125\" cy=\"108\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"164\" cy=\"108\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"200\" cy=\"108\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"236\" cy=\"108\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"275\" cy=\"108\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"320\" cy=\"108\" r=\"4.5\" fill=\"#c9a04a\"/><text x=\"24\" y=\"94\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">B組</text><text x=\"316\" y=\"94\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">ばらつき大 → 分散 大</text><line x1=\"200\" y1=\"26\" x2=\"200\" y2=\"120\" stroke=\"#6ab08d\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/><text x=\"200\" y=\"138\" fill=\"#6ab08d\" font-size=\"10\" text-anchor=\"middle\">平均はどちらも60点</text></svg>", "terms": [["偏差", "1人1人の値から平均を引いた差。平均からの離れ具合"], ["分散", "偏差を2乗して平均した値。ばらつきの大きさ"], ["標準偏差", "分散の平方根。単位が元にもどった、ばらつきのものさし"]], "think": "なぜ2乗するのかがカギ。平均からの差（偏差）をそのまま全部たすと、プラスの差とマイナスの差が打ち消し合って、どんなデータでも必ず合計0になってしまう。そこで差を2乗して全部プラスにしてから平均する。これで「離れているほど大きい」数字がちゃんと残る。しかも2乗のおかげで、大きく離れた値ほど強くカウントされる。", "vs": "平均値は「どこに集まるか（中心）」、分散は「どれだけ散らばるか（幅）」。中心と幅の2つがそろって、はじめて分布のイメージが描ける。", "why_asked": "平均が同じ2つのグループは世の中に無数にある。品質管理でも投資でも、「ばらつきの大きさ」こそがリスクの正体なので、それを測る専用の数字が必要だった。", "usecase": "工場の品質管理（製品サイズのばらつき監視）、投資のリスク評価（値動きの荒さ）、テストの難易度分析。「安定しているか」を数字で語る場面すべてで使う。", "opt": ["正解。平均からの離れ具合を2乗して平均した値で、散らばりの大きさを表す。", "平均値は2クラスとも60点で同じ。今回知りたい「違い」は、まさに平均では見えない部分。", "中央値も分布の真ん中を表す代表値で、散らばりの大きさそのものは表さない。", "合計点は人数と平均で決まる値。散らばり方が違っても、合計は同じになり得る。"]}'),

  ('stats1-q08', 'データのようす（記述統計）',
   'テストの分散を計算したら625だった。ただし単位が「点×点（点の2乗）」で感覚がつかめない。点数の感覚のまま「ばらつき」を扱うには、分散をどうすればいい？',
   NULL::text,
   '["平方根（√）をとる", "もう一度2乗して整える", "全体を人数で割り直す", "全体から平均値を引く"]',
   0, '[0]', 'single',
   '{"asked": "分散と標準偏差の関係。", "point": "標準偏差＝√分散。2乗でふくらんだ単位を、平方根で元に戻した「ばらつきのものさし」。", "kid": "分散は、計算の途中で2乗したせいで単位まで2乗（点²）になってしまった数。平方根をとって単位を「点」に戻したものが標準偏差。意味はどちらも同じ「ばらつきの大きさ」。", "eg": "正方形の面積（cm²）から辺の長さ（cm）に戻すのと同じ。面積のままでは長さと比べられないので、√で「長さの世界」に帰ってくる。", "viz": "<svg viewBox=\"0 0 340 142\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"28\" y=\"18\" width=\"120\" height=\"40\" rx=\"8\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"88\" y=\"35\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">分散 625</text><text x=\"88\" y=\"50\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">単位：点²（ピンとこない）</text><line x1=\"152\" y1=\"38\" x2=\"188\" y2=\"38\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"196,38 187,33 187,43\" fill=\"#3b82f6\"/><text x=\"174\" y=\"28\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\">√ をとる</text><rect x=\"200\" y=\"18\" width=\"120\" height=\"40\" rx=\"8\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"260\" y=\"35\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">標準偏差 25</text><text x=\"260\" y=\"50\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">単位：点（感覚で読める）</text><rect x=\"125\" y=\"88\" width=\"150\" height=\"26\" fill=\"#3b82f6\" opacity=\"0.16\"/><line x1=\"20\" y1=\"114\" x2=\"320\" y2=\"114\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"125\" y1=\"88\" x2=\"125\" y2=\"118\" stroke=\"#2a2f3f\"/><text x=\"125\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">35</text><line x1=\"200\" y1=\"88\" x2=\"200\" y2=\"118\" stroke=\"#2a2f3f\"/><text x=\"200\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">平均60</text><line x1=\"275\" y1=\"88\" x2=\"275\" y2=\"118\" stroke=\"#2a2f3f\"/><text x=\"275\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">85</text><text x=\"200\" y=\"80\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\">平均 ± 25点 のはば</text></svg>", "terms": [["標準偏差", "分散の平方根。元の単位で読める、ばらつきのものさし"], ["平方根（√）", "2乗すると元の数になる数。√625=25"]], "think": "なぜわざわざ2段階にするのか。分散の計算で2乗が必要だったのは、そうしないと偏差の合計が0になってしまうから。でも「ばらつきは625点²です」と言われてもピンとこない。√625=25点に戻せば、「平均60点から、だいたい25点くらい上下に散らばっている」と点数の感覚で読める。計算の都合（2乗）と人間の感覚（元の単位）の橋渡しをするのが平方根。", "vs": "分散と標準偏差は同じ情報の2つの姿。単位が2乗のままなのが分散、元の単位に戻したのが標準偏差。人に説明するときは標準偏差、数式の途中では分散、と使い分けられることが多い。", "why_asked": "「平均±標準偏差」という形で分布のおおよその範囲を語るのが統計の共通語だから。正規分布なら平均±標準偏差1個分に約68%が入る、というあとの単元も、ここが土台になる。", "usecase": "模試の成績表（平均と標準偏差から偏差値を計算）、製品検査の合格範囲（平均±3×標準偏差）、気象の「平年並み」の幅の決め方。", "opt": ["正解。平方根をとれば√625=25で、単位が点に戻る。これが標準偏差。", "もう一度2乗すると単位は点の4乗になり、ますます感覚から遠ざかる。", "分散はすでに人数で割ってある値なので、もう一度割っても単位は点²のまま変わらない。", "平均値を引いても単位は点²のままで、意味のある数字にならない。"]}'),

  ('stats1-q09', 'データのようす（記述統計）',
   '全国模試で70点を取り、偏差値は60だった。この「偏差値60」の意味に一番近いのはどれ？',
   NULL::text,
   '["平均より標準偏差1個分だけ上", "満点の60%を取れたということ", "受験者の上位60%に入る位置", "平均点より10点高かったということ"]',
   0, '[0]', 'single',
   '{"asked": "偏差値という数字の正体。", "point": "偏差値50＝ちょうど平均。そこから標準偏差1個分離れるごとに±10。60なら平均+1個分。", "kid": "偏差値は「平均を50、ばらつき1個分を10」にそろえ直した点数。テストごとに平均も難しさも違うので、素点のままでは比べられない。どのテストも同じものさしに換算したのが偏差値。", "eg": "国ごとに通貨が違うと値段を比べられないので、いったん円に両替して比べる。偏差値は「どのテストの点数でも両替できる共通通貨」。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M20 118 C 100 118, 115 26, 170 26 C 225 26, 240 118, 320 118\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"118\" x2=\"320\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"20.0\" y1=\"118\" x2=\"20.0\" y2=\"123\" stroke=\"#2a2f3f\"/><text x=\"20.0\" y=\"136\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">30</text><line x1=\"95.0\" y1=\"118\" x2=\"95.0\" y2=\"123\" stroke=\"#2a2f3f\"/><text x=\"95.0\" y=\"136\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">40</text><line x1=\"170.0\" y1=\"118\" x2=\"170.0\" y2=\"123\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"136\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">50</text><line x1=\"245.0\" y1=\"118\" x2=\"245.0\" y2=\"123\" stroke=\"#2a2f3f\"/><text x=\"245.0\" y=\"136\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">60</text><line x1=\"320.0\" y1=\"118\" x2=\"320.0\" y2=\"123\" stroke=\"#2a2f3f\"/><text x=\"320.0\" y=\"136\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">70</text><line x1=\"170.0\" y1=\"118\" x2=\"170.0\" y2=\"30\" stroke=\"#2a2f3f\" stroke-dasharray=\"4 3\"/><text x=\"170.0\" y=\"22\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">平均＝偏差値50</text><line x1=\"245.0\" y1=\"118\" x2=\"245.0\" y2=\"52\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><circle cx=\"245.0\" cy=\"52\" r=\"4.5\" fill=\"#3b82f6\"/><text x=\"253.0\" y=\"46\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">あなた＝偏差値60</text><text x=\"253.0\" y=\"62\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">平均より1個分上</text><text x=\"253.0\" y=\"76\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">（上位およそ16%）</text></svg>", "terms": [["偏差値", "平均50・標準偏差10に換算した成績。50が平均、60は平均+1個分"], ["標準化（z値）", "平均0・標準偏差1に換算すること。偏差値はz値を10倍して50を足したもの"]], "think": "70点という素点の価値は、テストしだいで変わる。平均60点・標準偏差10点のテストなら「平均から標準偏差1個分上」で偏差値60。でも平均75点のテストなら平均以下で、偏差値は50を切る。素点そのものではなく「平均から、ばらつき何個分離れているか」に換算するから、難しさの違うテスト同士でも自分の位置を比べられる。得点分布が正規分布に近ければ、偏差値60は上位およそ16%にあたる。", "vs": "「偏差値60＝上位60%」でも「満点の60%」でもない。偏差値は割合ではなく「平均からの距離」を表す数字。パーセントの仲間だと思い込むのが一番多い勘違い。", "why_asked": "「難しさの違う試験の結果を比べたい」という要求は入試に限らず普遍的で、統計の核心概念である標準化（z値）の入り口になっている。日本人に一番なじみ深い統計量でもある。", "usecase": "模試の合格判定はまさに偏差値。ビジネスでも、部署ごとに基準の違う評価点を比べるときに同じ発想（標準化）を使う。", "opt": ["正解。偏差値は平均=50、標準偏差1個分=10と決めた換算値なので、60は平均+1個分の位置。", "偏差値は満点に対する割合ではない。満点の6割でも、平均しだいで偏差値は50より上にも下にもなる。", "上位60%なら平均より下の位置になってしまう。偏差値60は逆に、上位およそ16%という平均よりだいぶ上の位置。", "平均から「何点」ではなく「標準偏差何個分」で測るのが偏差値。ばらつきの小さい試験なら、同じ10点差でももっと大きな偏差値の差になる。"]}'),

  ('stats1-q10', 'データのようす（記述統計）',
   '100人の点数を低い順に並べて、人数で4等分した。下から数えて75番目あたりの区切りの値を何と呼ぶ？',
   NULL::text,
   '["第3四分位数", "第1四分位数", "中央値", "最頻値"]',
   0, '[0]', 'single',
   '{"asked": "データを4等分する区切りの名前。", "point": "低い方から25%・50%・75%の区切りが第1・第2・第3四分位数。75番目なら第3。", "kid": "全員を点数順に一列に並べて4つのグループに等分したときの、3つの区切り目の値。真ん中の区切り（第2四分位数）は中央値と同じもの。", "eg": "マラソン大会で参加者を「先頭集団・前半組・後半組・最後尾組」に4等分するときの、3本の区切りテープ。ゴールから見て3本目ではなく、後ろから3本目のテープ地点が第3四分位数。", "viz": "<svg viewBox=\"0 0 340 126\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"20\" y=\"52\" width=\"75\" height=\"26\" fill=\"#3b82f6\" opacity=\"0.32\"/><text x=\"57\" y=\"69\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">25人</text><rect x=\"95\" y=\"52\" width=\"75\" height=\"26\" fill=\"#3b82f6\" opacity=\"0.16\"/><text x=\"132\" y=\"69\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">25人</text><rect x=\"170\" y=\"52\" width=\"75\" height=\"26\" fill=\"#3b82f6\" opacity=\"0.32\"/><text x=\"207\" y=\"69\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">25人</text><rect x=\"245\" y=\"52\" width=\"75\" height=\"26\" fill=\"#3b82f6\" opacity=\"0.16\"/><text x=\"282\" y=\"69\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">25人</text><rect x=\"20\" y=\"52\" width=\"300\" height=\"26\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"20\" y=\"40\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">低い←</text><text x=\"320\" y=\"40\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">→高い</text><line x1=\"95\" y1=\"52\" x2=\"95\" y2=\"86\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"95\" y=\"100\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">第1四分位数</text><text x=\"95\" y=\"113\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">下から25%</text><line x1=\"170\" y1=\"52\" x2=\"170\" y2=\"86\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"170\" y=\"100\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">中央値(第2)</text><text x=\"170\" y=\"113\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">下から50%</text><line x1=\"245\" y1=\"52\" x2=\"245\" y2=\"86\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"245\" y=\"100\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">第3四分位数</text><text x=\"245\" y=\"113\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">下から75%</text><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">100人を点数順に並べて4等分する</text></svg>", "terms": [["四分位数", "データを4等分する3つの区切りの値"], ["四分位範囲", "第1四分位数から第3四分位数までの幅。真ん中の50%が入る範囲"], ["パーセンタイル", "下から何%の位置かで表す言い方。第3四分位数=75パーセンタイル"]], "think": "中央値だけだと「真ん中がどこか」しか分からない。区切りを25%と75%の位置にも置くと、「真ん中の50%の人がどの範囲に収まっているか」（四分位範囲）が分かる。これがそのまま箱ひげ図の箱になる。並び順で区切る仕組みなので、中央値と同じく外れ値に強い。", "vs": "第1四分位数は下から25%、第3四分位数は下から75%。「第3」と聞いて上から数えたくなるが、四分位数は必ず下から数える。", "why_asked": "平均と標準偏差が外れ値に弱いのに対し、四分位数は並び順ベースで頑丈。箱ひげ図や、外れ値の判定基準（四分位範囲の1.5倍ルール）など、実務の道具の部品になっている。", "usecase": "学力調査で「真ん中の50%の範囲」を示すとき。求人の給与レンジの「25パーセンタイル〜75パーセンタイル」表記も同じ考え方。", "opt": ["正解。下から数えて75%の位置の区切りが第3四分位数。", "第1四分位数は下から25%、つまり25番目あたりの区切りの値。", "中央値は下から50%、50番目あたりの区切りで、第2四分位数と同じもの。", "最頻値は一番多く登場した点数のことで、並び順の区切りとは関係がない。"]}'),

  ('stats1-q11', 'データのようす（記述統計）',
   '箱ひげ図で、「箱」の中に入っているのは全データのおよそ何%？',
   NULL::text,
   '["約50%", "約25%", "約75%", "ほぼ100%"]',
   0, '[0]', 'single',
   '{"asked": "箱ひげ図の「箱」が表している範囲。", "point": "箱の両端は第1四分位数と第3四分位数。だから箱の中身は「真ん中の約50%」。", "kid": "箱ひげ図は、データの散らばりを「箱」と「ひげ」で描いた図。箱は真ん中の50%の人がいる範囲、箱の中の線は中央値、ひげはそこから端の方までの範囲、ポツンと離れた外れ値は点で別に描く。", "eg": "学年の通学時間調査なら、箱は「ふつうの人たち（真ん中の半分）」の範囲、ひげは特に早い人・遅い人まで、離れた点は片道2時間の遠距離通学者（外れ値）。", "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"40\" y1=\"64\" x2=\"110\" y2=\"64\" stroke=\"#8892a4\"/><line x1=\"230\" y1=\"64\" x2=\"300\" y2=\"64\" stroke=\"#8892a4\"/><line x1=\"40\" y1=\"54\" x2=\"40\" y2=\"74\" stroke=\"#8892a4\"/><line x1=\"300\" y1=\"54\" x2=\"300\" y2=\"74\" stroke=\"#8892a4\"/><rect x=\"110\" y=\"44\" width=\"120\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.2\" stroke=\"#3b82f6\"/><line x1=\"162\" y1=\"44\" x2=\"162\" y2=\"84\" stroke=\"#e8eaf0\" stroke-width=\"2\"/><circle cx=\"322\" cy=\"64\" r=\"3.5\" fill=\"#c47070\"/><text x=\"40\" y=\"104\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">最小</text><text x=\"110\" y=\"104\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">第1四分位</text><text x=\"162\" y=\"104\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">中央値</text><text x=\"230\" y=\"104\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">第3四分位</text><text x=\"300\" y=\"104\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">最大</text><text x=\"322\" y=\"52\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">外れ値</text><path d=\"M110 36 L110 30 L230 30 L230 36\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"170\" y=\"22\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">箱＝真ん中の約50%が入る範囲</text></svg>", "terms": [["箱ひげ図", "最小・第1四分位・中央値・第3四分位・最大の5つの数で分布を要約した図"], ["ひげ", "箱の外に伸びる線。外れ値を除いた端までの範囲を表す"]], "think": "箱の下端が第1四分位数（下から25%）、上端が第3四分位数（下から75%）。75から25を引いて、箱の中は50%。箱が短ければ真ん中の半分がぎゅっと集まっている、長ければ散らばっている、と読む。ヒストグラムより場所を取らないので、複数のグループを横に並べて比べるのが得意技。", "vs": "ヒストグラムは1つの分布の形を細かく見る道具、箱ひげ図は複数の分布を並べて比べる道具。箱の中の線は中央値であって平均値ではない点にも注意（平均を×印で描き足す流儀もある）。", "why_asked": "たった5つの数字で分布を要約できる、実務でいちばんよく見る比較グラフの1つだから。読み方を知らないと、分析レポートや論文の図が読めない。", "usecase": "クラス別の成績比較、部署別の残業時間比較、A/Bテストの結果比較。「グループごとの分布を横に並べて見たい」ときの定番。", "opt": ["正解。箱は第1四分位数から第3四分位数まで、つまり真ん中の約50%が入る範囲。", "約25%は、端から第1四分位数までのような1区画ぶんの割合。箱はその2区画ぶん。", "約75%は、下から第3四分位数までの割合。箱はそこから下側の25%を除いた範囲。", "ほぼ100%を覆うのは、ひげの端から端まで。箱だけならその真ん中の半分。"]}'),

  ('stats1-q12', 'データのようす（記述統計）',
   '「気温が高い日ほどアイスが売れる」という2つの数の関係を目で確かめたい。最初に描くグラフはどれ？',
   NULL::text,
   '["散布図", "ヒストグラム", "箱ひげ図", "円グラフ"]',
   0, '[0]', 'single',
   '{"asked": "2つの量の関係を見るための基本グラフ。", "point": "横軸に片方、縦軸にもう片方をとり、1日=1つの点を打つのが散布図。点の並びが右上がりなら正の相関。", "kid": "1日ごとに「その日の気温」と「その日の売上」のペアを、1つの点として打つ。点がたくさん集まると、右上がり（片方が増えるともう片方も増える）や右下がりの傾向が目に見えてくる。", "eg": "クラス全員の「勉強時間とテストの点」を1人1点で打てば、「勉強するほど点が高い」傾向が点の帯になって浮かび上がる。表の数字を1行ずつ読むより一瞬で分かる。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"44\" y1=\"16\" x2=\"44\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"44\" y1=\"118\" x2=\"316\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><circle cx=\"62\" cy=\"104\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"80\" cy=\"99\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"96\" cy=\"92\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"112\" cy=\"96\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"130\" cy=\"84\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"146\" cy=\"78\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"166\" cy=\"81\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"182\" cy=\"66\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"200\" cy=\"58\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"218\" cy=\"62\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"238\" cy=\"46\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"258\" cy=\"38\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"278\" cy=\"42\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"296\" cy=\"30\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"56\" y1=\"108\" x2=\"304\" y2=\"28\" stroke=\"#8892a4\" stroke-dasharray=\"5 4\"/><text x=\"180\" y=\"134\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">気温（1日＝1つの点）</text><text x=\"30\" y=\"70\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\" transform=\"rotate(-90 30 70)\">アイスの売上</text><text x=\"150\" y=\"24\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"start\" font-weight=\"600\">右上がり＝正の相関</text></svg>", "terms": [["散布図", "2つの量のペアを平面上の点で表したグラフ"], ["正の相関", "片方が増えるともう片方も増える傾向。点が右上がりに並ぶ"], ["負の相関", "片方が増えるともう片方が減る傾向。点が右下がりに並ぶ"]], "think": "ヒストグラムや箱ひげ図は「1つの量」の散らばりを見る道具で、2つの量の「関係」は描けない。関係を見るには、2つの値の組を平面上の1つの点に対応させる。点が右上がりに並べば正の相関、右下がりなら負の相関、丸く散らばれば関係なし。あとで習う相関係数は、この点の並び具合を数字1つにしたもの。", "vs": "「相関がある＝原因と結果」ではないことに注意。本当に因果がある場合もあれば、別の何か（たとえば季節）が両方を動かしているだけの場合（疑似相関）もある。散布図は「一緒に動く傾向」を見せる道具、と割り切って読む。", "why_asked": "相関・回帰という統計の主要単元は、すべて散布図の上に建っている。数字（相関係数）だけ見て散布図を見ないと、外れ値1つが作った見せかけの相関にだまされる。", "usecase": "広告費と売上、勉強時間と成績、気温と電力需要。「2つの指標に関係はあるか」を調べる分析は、実務でもまず散布図から始まる。", "opt": ["正解。2つの量のペアを1つの点として打ち、関係の傾向を目で見るグラフ。", "ヒストグラムは1つの量の分布の形を見る道具で、2つの量の関係は描けない。", "箱ひげ図はグループごとの散らばりを比べる道具で、ペアの関係を見るものではない。", "円グラフは全体に対する内訳の割合を見る道具で、2つの量の関係とは関係がない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
